import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import * as TooltipPrimitive from "@radix-ui/react-tooltip";
import type { ComponentProps } from "react";
import { cn } from "./lib/cn";
import "./tooltip.css";

export const Tooltip = TooltipPrimitive.Root;
export const TooltipTrigger = TooltipPrimitive.Trigger;

/**
 * The first tooltip waits 300ms; neighbours then show at once for 500ms.
 * Tooltips are labels, not panels, so their content is not hoverable: moving
 * along a toolbar switches straight to the next label.
 */
export function TooltipProvider({
  delayDuration = 300,
  skipDelayDuration = 500,
  disableHoverableContent = true,
  ...props
}: ComponentProps<typeof TooltipPrimitive.Provider>) {
  return (
    <TooltipPrimitive.Provider
      delayDuration={delayDuration}
      skipDelayDuration={skipDelayDuration}
      disableHoverableContent={disableHoverableContent}
      {...props}
    />
  );
}

export function TooltipContent({
  className,
  sideOffset = 6,
  shortcut,
  children,
  ...props
}: ComponentProps<typeof TooltipPrimitive.Content> & {
  /** Keyboard shortcut shown after the label, e.g. "⌘D". */
  shortcut?: string;
}) {
  return (
    <TooltipPrimitive.Portal>
      <TooltipPrimitive.Content
        data-slot="tooltip-content"
        sideOffset={sideOffset}
        className={cn(
          "z-50 inline-flex max-w-60 items-center gap-2 rounded-control bg-foreground px-2.5 py-1.5 text-xs leading-4 font-medium text-background shadow-feedback",
          className,
        )}
        {...props}
      >
        {children}
        {shortcut && <kbd data-slot="tooltip-shortcut">{shortcut}</kbd>}
      </TooltipPrimitive.Content>
    </TooltipPrimitive.Portal>
  );
}

/* tooltip.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* The first tooltip fades in; while warm, neighbours swap with no animation. */
  [data-slot="tooltip-content"][data-state="delayed-open"] {
    animation: caliper-fade-in var(--duration-fast) var(--ease-out);
  }
  [data-slot="tooltip-shortcut"] {
    display: inline-flex;
    align-items: center;
    height: 18px;
    padding: 0 5px;
    border-radius: 4px;
    font-family: var(--font-mono);
    font-size: 12px;
    font-weight: 500;
    background: color-mix(in srgb, var(--background) 16%, transparent);
  }

  [data-slot="tooltip-content"][data-state="closed"] {
    animation: caliper-fade-out var(--duration-fast) var(--ease-in) forwards;
    pointer-events: none;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="tooltip-content"] {
      animation: none;
    }
    /* Preserve the exit name for Radix Presence's completion matcher, including
       a preference changed during exit. No visual motion or unmount timer. */
    [data-slot="tooltip-content"][data-state="closed"] {
      animation: caliper-fade-out var(--duration-instant) var(--ease-in) forwards !important;
    }
  }
}
